import 'address_details_view.dart';

class WalletAddressesView extends ConsumerStatefulWidget {
  const WalletAddressesView({
    super.key,
    required this.walletId,
    this.addressType,
    this.title,
  });

  static const String routeName = "/walletAddressesView";

  final String walletId;

  /// Only list addresses of this type (e.g. the type picked on the
  /// receive screen). All wallet addresses when null.
  final AddressType? addressType;
  final String? title;

  @override
  ConsumerState<WalletAddressesView> createState() =>
      _WalletAddressesViewState();
}

class _WalletAddressesViewState extends ConsumerState<WalletAddressesView> {
  final bool isDesktop = Util.isDesktop;

  final String _searchString = "";

  Future<List<int>> _search(String term) async {
    if (term.isEmpty) {
      return MainDB.instance
          .getAddresses(widget.walletId)
          .filter()
          .group(
            (q) => q
                .subTypeEqualTo(AddressSubType.change)
                .or()
                .subTypeEqualTo(AddressSubType.receiving),
          )
          .and()
          .not()
          .typeEqualTo(AddressType.nonWallet)
          .optional(
            widget.addressType != null,
            (q) => q.and().typeEqualTo(widget.addressType!),
          )
          .sortByDerivationIndex()
          .idProperty()
          .findAll();
    }

    final labels =
        await MainDB.instance
            .getAddressLabels(widget.walletId)
            .filter()
            .group(
              (q) => q
                  .valueContains(term, caseSensitive: false)
                  .or()
                  .addressStringContains(term, caseSensitive: false)
                  .or()
                  .group(
                    (q) => q.tagsIsNotNull().and().tagsElementContains(
                      term,
                      caseSensitive: false,
                    ),
                  ),
            )
            .findAll();

    if (labels.isEmpty) {
      return [];
    }

    return MainDB.instance
        .getAddresses(widget.walletId)
        .filter()
        .anyOf<AddressLabel, Address>(
          labels,
          (q, e) => q.valueEqualTo(e.addressString),
        )
        .group(
          (q) => q
              .subTypeEqualTo(AddressSubType.change)
              .or()
              .subTypeEqualTo(AddressSubType.receiving),
        )
        .and()
        .not()
        .typeEqualTo(AddressType.nonWallet)
        .optional(
          widget.addressType != null,
          (q) => q.and().typeEqualTo(widget.addressType!),
        )
        .sortByDerivationIndex()
        .idProperty()
        .findAll();
  }

  @override
  Widget build(BuildContext context) {
    final coin = ref.watch(pWalletCoin(widget.walletId));

    return ConditionalParent(
      condition: !isDesktop,
      builder:
          (child) => Background(
            child: Scaffold(
              backgroundColor:
                  Theme.of(context).extension<StackColors>()!.background,
              appBar: AppBar(
                backgroundColor:
                    Theme.of(
                      context,
                    ).extension<StackColors>()!.backgroundAppBar,
                leading: AppBarBackButton(
                  onPressed: () {
                    Navigator.of(context).pop();
                  },
                ),
                titleSpacing: 0,
                title: Text(
                  widget.title ?? "Wallet addresses",
                  style: STextStyles.navBarTitle(context),
                ),
              ),
              body: Padding(padding: const EdgeInsets.all(16), child: child),
            ),
          ),
      child: SafeArea(
        child: Column(
          children: [
            Expanded(
              child: FutureBuilder(
                future: _search(_searchString),
                builder: (context, AsyncSnapshot<List<int>> snapshot) {
                  if (snapshot.connectionState == ConnectionState.done &&
                      snapshot.data != null) {
                    // listview
                    return ListView.separated(
                      itemCount: snapshot.data!.length,
                      separatorBuilder: (_, __) => Container(height: 10),
                      itemBuilder:
                          (_, index) => AddressCard(
                            walletId: widget.walletId,
                            addressId: snapshot.data![index],
                            coin: coin,
                            onPressed: () {
                              Navigator.of(context).pushNamed(
                                AddressDetailsView.routeName,
                                arguments: Tuple2(
                                  snapshot.data![index],
                                  widget.walletId,
                                ),
                              );
                            },
                          ),
                    );
                  } else {
                    return const Center(
                      child: LoadingIndicator(height: 200, width: 200),
                    );
                  }
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}
